"use client";

import { useThree } from "@react-three/fiber";
import type { ThreeElements, ThreeEvent } from "@react-three/fiber";
import { useEffect, useId, useLayoutEffect, useRef } from "react";
import type { RefObject } from "react";
import { BoxGeometry, MathUtils, MeshBasicMaterial, Vector3 } from "three";

import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";

import type { WornPart } from "./accessories/registry";
import { wornParts } from "./accessories/registry";
import { disc, roundedBox } from "./geometry";
import { AgentLiveContext, armPivotNames } from "./held-pose";
import type { Outfit } from "./outfit";
import { outfitSlots, rolePresets } from "./outfit";
import { PieceDrop, useOutfitPop } from "./outfit-motion";
import { Part } from "./part";
import {
  anchorPositions,
  armSize,
  bodyBase,
  bodySize,
  eyeSize,
  legOffsets,
  legSize,
  shoulder,
} from "./rig";
import { createRadialFadeTexture } from "./textures";
import type { AgentAction, AgentRole } from "./types";
import type { AgentMotion, AgentPointer } from "./use-agent-rig";
import { useAgentRig } from "./use-agent-rig";

export type { AgentMotion, AgentPointer } from "./use-agent-rig";

export interface AgentProps extends Omit<ThreeElements["group"], "children"> {
  role: AgentRole;
  outfit?: Outfit;
  animateOutfit?: boolean;
  action?: AgentAction;
  actionRef?: RefObject<AgentAction>;
  pointer?: RefObject<AgentPointer>;
  motion?: AgentMotion;
  shadow?: boolean;
}

const seedFromId = (id: string) => {
  let hash = 0;
  for (const character of id) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 9973;
  }
  return hash / 9973;
};

const bodyGeometry = roundedBox(
  bodySize.width,
  bodySize.height,
  bodySize.depth,
  bodySize.radius,
  5
);
const legGeometry = roundedBox(
  legSize.width,
  legSize.height,
  legSize.depth,
  legSize.radius,
  3
);
const armGeometry = roundedBox(
  armSize.length,
  armSize.height,
  armSize.depth,
  armSize.radius,
  4
);
const eyeGeometry = roundedBox(
  eyeSize.size,
  eyeSize.size,
  eyeSize.depth,
  0.014,
  2
);
const highlightGeometry = roundedBox(0.036, 0.036, 0.01, 0.004, 1);

const shadowMaterial = new MeshBasicMaterial({
  alphaMap: createRadialFadeTexture(),
  color: "#3b2a1f",
  depthWrite: false,
  opacity: 0.28,
  toneMapped: false,
  transparent: true,
});

const hitSize = { depth: 1.3, height: 1.9, width: 1.8 };
const hitGeometry = new BoxGeometry(
  hitSize.width,
  hitSize.height,
  hitSize.depth
);
const hitMaterial = new MeshBasicMaterial({ visible: false });
const hitLocal = new Vector3();

type PointerLook = Omit<AgentPointer, "presses">;

const pointerAt = (
  event: ThreeEvent<PointerEvent>,
  hovered: boolean
): PointerLook => {
  hitLocal.copy(event.point);
  event.object.worldToLocal(hitLocal);
  return {
    hovered,
    x: MathUtils.clamp(hitLocal.x / (hitSize.width / 2), -1, 1),
    y: MathUtils.clamp(hitLocal.y / (hitSize.height / 2), -1, 1),
  };
};

const HitProxy = ({
  onPointer,
  onPress,
}: {
  onPointer: (look: PointerLook) => void;
  onPress: () => void;
}) => {
  const isHovering = useRef(false);
  const invalidate = useThree((state) => state.invalidate);

  useEffect(
    () => () => {
      if (isHovering.current) {
        document.body.style.cursor = "";
      }
    },
    []
  );

  return (
    <mesh
      geometry={hitGeometry}
      material={hitMaterial}
      onClick={() => {
        onPress();
        invalidate();
      }}
      onPointerMove={(event) => onPointer(pointerAt(event, isHovering.current))}
      onPointerOut={(event) => {
        isHovering.current = false;
        onPointer(pointerAt(event, false));
        document.body.style.cursor = "";
      }}
      onPointerOver={(event) => {
        event.stopPropagation();
        isHovering.current = true;
        onPointer(pointerAt(event, true));
        document.body.style.cursor = "pointer";
      }}
      position={[0, hitSize.height / 2, 0]}
    />
  );
};

const Eye = ({ side }: { side: 1 | -1 }) => (
  <group position={[side * eyeSize.spacing, 0, 0]}>
    <Part geometry={eyeGeometry} material="eye" />
    <Part
      geometry={highlightGeometry}
      material="highlight"
      position={[-0.03, 0.03, eyeSize.depth / 2]}
      receiveShadow={false}
    />
  </group>
);

const Worn = ({ parts }: { parts: readonly WornPart[] }) =>
  parts.map(({ key, Wear }) => (
    <PieceDrop key={key}>
      <Wear />
    </PieceDrop>
  ));

export const Agent = ({
  role,
  outfit,
  animateOutfit = false,
  action = "idle",
  actionRef,
  pointer,
  motion,
  shadow = true,
  ...groupProps
}: AgentProps) => {
  const prefersReducedMotion = usePrefersReducedMotion();
  const resolvedMotion = motion ?? (prefersReducedMotion ? "reduced" : "full");
  const seed = seedFromId(useId());
  const ownPointer = useRef<AgentPointer>({
    hovered: false,
    presses: 0,
    x: 0,
    y: 0,
  });
  const { attach, attachLeg, liveAction } = useAgentRig({
    action,
    actionRef,
    motion: resolvedMotion,
    pointer: pointer ?? ownPointer,
    seed,
  });
  const worn = outfit ?? rolePresets[role];
  const parts = wornParts(worn);
  const isDressing = animateOutfit && resolvedMotion === "full";
  const dressing = useRef(false);
  const pop = useOutfitPop(
    outfitSlots.map((slot) => worn[slot]).join("|"),
    isDressing
  );

  useLayoutEffect(() => {
    dressing.current = isDressing;
  }, [isDressing]);

  return (
    <AgentLiveContext value={{ dressing, liveAction, motion: resolvedMotion }}>
      <group {...groupProps} dispose={null} name={`agent-${role}-${action}`}>
        {pointer ? null : (
          <HitProxy
            onPointer={(look) => {
              Object.assign(ownPointer.current, look);
            }}
            onPress={() => {
              ownPointer.current.presses += 1;
            }}
          />
        )}
        {shadow ? (
          <group ref={attach("shadow")}>
            <mesh
              geometry={disc()}
              material={shadowMaterial}
              position={[0, 0.004, 0.04]}
              rotation-x={-Math.PI / 2}
              scale={[0.95, 0.75, 1]}
            />
          </group>
        ) : null}
        <group ref={pop}>
          <group ref={attach("root")}>
            {legOffsets.map((x, index) => (
              <group
                key={x}
                position={[x, legSize.height, legSize.z]}
                ref={attachLeg(index)}
              >
                <Part
                  castShadow
                  geometry={legGeometry}
                  material="clay"
                  position={[0, -legSize.height / 2, 0]}
                />
              </group>
            ))}
            <group position={[0, bodyBase, 0]} ref={attach("body")}>
              <Part
                castShadow
                geometry={bodyGeometry}
                material="clay"
                position={[0, bodySize.height / 2, 0]}
              />
              <group position={anchorPositions.face}>
                <group ref={attach("eyes")}>
                  <Eye side={1} />
                  <Eye side={-1} />
                </group>
                <Worn parts={parts.face} />
              </group>
              <group position={anchorPositions.head}>
                <Worn parts={parts.head} />
              </group>
              <group position={anchorPositions.torso}>
                <Worn parts={parts.torso} />
              </group>
              <Worn parts={parts.body} />
              <group
                name={armPivotNames.right}
                position={[shoulder.x, shoulder.y, shoulder.z]}
                ref={attach("armRight")}
              >
                <Part
                  castShadow
                  geometry={armGeometry}
                  material="clay"
                  position={[armSize.length / 2, 0, 0]}
                />
                <Worn parts={parts.rightArm} />
              </group>
              <group
                name={armPivotNames.left}
                position={[-shoulder.x, shoulder.y, shoulder.z]}
                ref={attach("armLeft")}
              >
                <group scale={[-1, 1, 1]}>
                  <Part
                    castShadow
                    geometry={armGeometry}
                    material="clay"
                    position={[armSize.length / 2, 0, 0]}
                  />
                  <Worn parts={parts.leftArm} />
                </group>
              </group>
            </group>
          </group>
        </group>
      </group>
    </AgentLiveContext>
  );
};

import type { AgentRole } from "./types";

export const outfitPieceIds = {
  face: ["none", "round-glasses", "pixel-shades", "teal-visor"],
  head: [
    "none",
    "yellow-hard-hat",
    "white-hard-hat",
    "safety-helmet",
    "deerstalker",
    "mortarboard",
    "headset",
    "goggles",
  ],
  held: [
    "none",
    "laptop",
    "book",
    "magnifier",
    "tape-measure",
    "pointer",
    "pencil",
  ],
  offhand: ["none", "clipboard", "blueprint-roll", "tablet"],
  torso: [
    "none",
    "safety-vest",
    "tweed-vest",
    "lab-coat",
    "plaid-coat",
    "knit-sweater",
  ],
} as const;

export type OutfitSlot = keyof typeof outfitPieceIds;

export const outfitSlots = [
  "head",
  "face",
  "torso",
  "held",
  "offhand",
] as const satisfies readonly OutfitSlot[];

export type OutfitPieceId<Slot extends OutfitSlot = OutfitSlot> =
  (typeof outfitPieceIds)[Slot][number];

export type Outfit = { readonly [Slot in OutfitSlot]: OutfitPieceId<Slot> };

export const rolePresets = {
  analyst: {
    face: "teal-visor",
    head: "goggles",
    held: "pointer",
    offhand: "none",
    torso: "lab-coat",
  },
  architect: {
    face: "none",
    head: "white-hard-hat",
    held: "tape-measure",
    offhand: "blueprint-roll",
    torso: "none",
  },
  builder: {
    face: "none",
    head: "yellow-hard-hat",
    held: "laptop",
    offhand: "none",
    torso: "safety-vest",
  },
  debugger: {
    face: "none",
    head: "deerstalker",
    held: "magnifier",
    offhand: "none",
    torso: "plaid-coat",
  },
  inspector: {
    face: "none",
    head: "safety-helmet",
    held: "pencil",
    offhand: "clipboard",
    torso: "none",
  },
  orchestrator: {
    face: "pixel-shades",
    head: "headset",
    held: "none",
    offhand: "tablet",
    torso: "none",
  },
  researcher: {
    face: "round-glasses",
    head: "mortarboard",
    held: "book",
    offhand: "none",
    torso: "tweed-vest",
  },
} as const satisfies Record<AgentRole, Outfit>;

export const isOutfitPiece = <Slot extends OutfitSlot>(
  slot: Slot,
  value: unknown
): value is OutfitPieceId<Slot> =>
  outfitPieceIds[slot].some((piece) => piece === value);

export const outfitsMatch = (first: Outfit, second: Outfit) =>
  outfitSlots.every((slot) => first[slot] === second[slot]);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useLayoutEffect, useRef } from "react";
import type { ReactNode } from "react";
import type { Group } from "three";

import { useAgentLive } from "./held-pose";

const dropSeconds = 0.46;
const dropHeight = 0.5;
const dropStartScale = 0.35;
const popSeconds = 0.34;
const popLift = 0.14;
const popStretch = 0.07;
const pending = Number.NaN;

const easeOutBack = (value: number) => {
  const overshoot = 1.9;
  const shifted = value - 1;
  return 1 + (overshoot + 1) * shifted ** 3 + overshoot * shifted ** 2;
};

const elapsedSince = (start: { current: number | null }, now: number) => {
  if (start.current === null) {
    return null;
  }
  if (Number.isNaN(start.current)) {
    start.current = now;
  }
  return now - start.current;
};

export const PieceDrop = ({ children }: { children: ReactNode }) => {
  const group = useRef<Group>(null);
  const dropStart = useRef<number | null>(null);
  const { dressing } = useAgentLive();
  const invalidate = useThree((state) => state.invalidate);

  useLayoutEffect(() => {
    const node = group.current;
    if (!(node && dressing.current)) {
      return;
    }
    dropStart.current = pending;
    node.position.y = dropHeight;
    node.scale.setScalar(dropStartScale);
    invalidate();
  }, [dressing, invalidate]);

  useFrame((state) => {
    const node = group.current;
    const elapsed = elapsedSince(dropStart, state.clock.elapsedTime);
    if (!node || elapsed === null) {
      return;
    }
    const progress = Math.min(1, elapsed / dropSeconds);
    const settle = easeOutBack(progress);
    node.position.y = dropHeight * (1 - settle);
    node.scale.setScalar(dropStartScale + (1 - dropStartScale) * settle);
    if (progress >= 1) {
      dropStart.current = null;
      node.position.y = 0;
      node.scale.setScalar(1);
    }
    state.invalidate();
  });

  return <group ref={group}>{children}</group>;
};

export const useOutfitPop = (signature: string, enabled: boolean) => {
  const group = useRef<Group>(null);
  const popStart = useRef<number | null>(null);
  const shownSignature = useRef(signature);
  const invalidate = useThree((state) => state.invalidate);

  useEffect(() => {
    if (shownSignature.current === signature) {
      return;
    }
    shownSignature.current = signature;
    if (enabled) {
      popStart.current = pending;
      invalidate();
    }
  }, [enabled, invalidate, signature]);

  useFrame((state) => {
    const node = group.current;
    const elapsed = elapsedSince(popStart, state.clock.elapsedTime);
    if (!node || elapsed === null) {
      return;
    }
    const progress = Math.min(1, elapsed / popSeconds);
    const arc = Math.sin(progress * Math.PI);
    node.position.y = arc * popLift;
    const squash = 1 - arc * popStretch * 0.5;
    node.scale.set(squash, 1 + arc * popStretch, squash);
    if (progress >= 1) {
      popStart.current = null;
      node.position.y = 0;
      node.scale.setScalar(1);
    }
    state.invalidate();
  });

  return group;
};

export const bodySize = { depth: 1, height: 1, radius: 0.13, width: 1.25 };

export const legSize = {
  depth: 0.2,
  height: 0.34,
  radius: 0.04,
  width: 0.16,
  z: 0.16,
};

export const legOffsets = [-0.5, -0.2, 0.2, 0.5] as const;

export const bodyBase = legSize.height - 0.03;

export const armSize = { depth: 0.38, height: 0.3, length: 0.34, radius: 0.07 };

export const shoulder = { x: bodySize.width / 2 - 0.05, y: 0.56, z: 0.04 };

export const handReach = armSize.length - 0.06;

export const eyeSize = { depth: 0.04, size: 0.13, spacing: 0.4, y: 0.75 };

export const anchorPositions = {
  face: [0, eyeSize.y, bodySize.depth / 2],
  head: [0, bodySize.height, 0],
  torso: [0, 0.32, bodySize.depth / 2],
} as const satisfies Record<string, readonly [number, number, number]>;

export const poseKeys = [
  "armLeftForward",
  "armLeftRaise",
  "armRightForward",
  "armRightRaise",
  "bodySquash",
  "bodyTiltX",
  "bodyTiltZ",
  "bodyYaw",
  "eyeOpen",
  "gazeX",
  "gazeY",
  "leg0",
  "leg1",
  "leg2",
  "leg3",
  "rootX",
  "rootY",
  "rootZ",
] as const;

export type PoseKey = (typeof poseKeys)[number];

export type Pose = Record<PoseKey, number>;

export const restArmRaise = 0.16;

export const createPose = (): Pose => ({
  armLeftForward: 0,
  armLeftRaise: restArmRaise,
  armRightForward: 0,
  armRightRaise: restArmRaise,
  bodySquash: 1,
  bodyTiltX: 0,
  bodyTiltZ: 0,
  bodyYaw: 0,
  eyeOpen: 1,
  gazeX: 0,
  gazeY: 0,
  leg0: 0,
  leg1: 0,
  leg2: 0,
  leg3: 0,
  rootX: 0,
  rootY: 0,
  rootZ: 0,
});

const neutralPose = createPose();

export const resetPose = (pose: Pose) => {
  for (const key of poseKeys) {
    pose[key] = neutralPose[key];
  }
};

export const blendPoses = (from: Pose, to: Pose, weight: number, out: Pose) => {
  for (const key of poseKeys) {
    out[key] = from[key] + (to[key] - from[key]) * weight;
  }
};

import type { Pose } from "./rig";
import { resetPose, restArmRaise } from "./rig";
import type { AgentAction, AgentReaction } from "./types";

interface ActionClip {
  keyTime: number;
  pose: (time: number, out: Pose) => void;
}

const tau = Math.PI * 2;

const breathe = (time: number, out: Pose, rate = 0.32) => {
  const cycle = Math.sin(time * tau * rate);
  out.bodySquash = 1 + cycle * 0.014;
  out.armLeftRaise += cycle * 0.03;
  out.armRightRaise += cycle * 0.03;
};

const stride = (time: number, out: Pose, speed: number, swing: number) => {
  const phase = time * speed;
  const step = Math.sin(phase);
  out.leg0 = step * swing;
  out.leg1 = -step * swing;
  out.leg2 = step * swing;
  out.leg3 = -step * swing;
  out.rootY = Math.abs(Math.cos(phase)) * 0.035;
  out.bodyTiltZ = step * 0.03;
};

const measureCycle = 2.6;

export const measureExtension = (time: number) => {
  const phase = (time % measureCycle) / measureCycle;
  if (phase < 0.45) {
    const local = phase / 0.45;
    return 1 - (1 - local) ** 3;
  }
  if (phase < 0.7) {
    return 1;
  }
  const local = (phase - 0.7) / 0.3;
  return 1 - local * local;
};

const checkCycle = 1.8;

export const checkStroke = (time: number) => {
  const phase = (time % checkCycle) / checkCycle;
  return phase > 0.55 && phase < 0.8
    ? Math.sin(((phase - 0.55) / 0.25) * Math.PI)
    : 0;
};

export const actionClips = {
  carry: {
    keyTime: 0.4,
    pose: (time, out) => {
      resetPose(out);
      stride(time, out, 7.5, 0.38);
      out.armLeftForward = 1.25;
      out.armRightForward = 1.25;
      out.armLeftRaise = 0.32;
      out.armRightRaise = 0.32;
      out.bodyTiltX = -0.06;
      out.gazeY = 0.01;
    },
  },
  celebrate: {
    keyTime: 0,
    pose: (time, out) => {
      resetPose(out);
      const bounce = Math.sin(time * 6.4);
      const airborne = Math.max(0, bounce);
      out.rootY = airborne * 0.24;
      out.bodySquash = 1 + (bounce < 0 ? bounce * 0.07 : airborne * 0.04);
      out.armLeftRaise = 1.1 + Math.sin(time * 12.8) * 0.2;
      out.armRightRaise = 1.1 + Math.sin(time * 12.8 + Math.PI) * 0.2;
      out.armLeftForward = 0.35;
      out.armRightForward = 0.35;
      out.leg0 = airborne * 0.25;
      out.leg3 = -airborne * 0.25;
      out.gazeY = 0.02;
    },
  },
  check: {
    keyTime: 1.25,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out, 0.26);
      const stroke = checkStroke(time);
      const glance = Math.sin(time * 0.9);
      out.armLeftForward = 1.18;
      out.armLeftRaise = 0.3;
      out.armRightForward = 1.05 + stroke * 0.12;
      out.armRightRaise = 0.12 - stroke * 0.18;
      out.bodyTiltX = 0.08 + stroke * 0.03;
      out.bodyYaw = -0.12;
      out.gazeX = -0.02 + glance * 0.012;
      out.gazeY = -0.03 + Math.max(0, glance) * 0.02;
    },
  },
  direct: {
    keyTime: 0.5,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out);
      const sweep = Math.sin(time * 2.4);
      out.armRightRaise = 0.65 + Math.sin(time * 4.8) * 0.18;
      out.armRightForward = 0.55 + sweep * 0.45;
      out.armLeftForward = 0.55;
      out.armLeftRaise = 0.22;
      out.bodyYaw = sweep * 0.16;
      out.bodyTiltZ = -0.03 + sweep * 0.025;
      out.gazeX = sweep * 0.03;
    },
  },
  idle: {
    keyTime: 0,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out);
      out.bodyTiltZ = Math.sin(time * 0.7) * 0.012;
      out.gazeX = Math.sin(time * 0.45) * 0.02;
    },
  },
  inspect: {
    keyTime: 1.2,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out, 0.24);
      const scan = Math.sin(time * 1.1);
      out.bodyTiltX = 0.1;
      out.bodyYaw = scan * 0.22;
      out.armRightForward = 0.85;
      out.armRightRaise = -0.12 + Math.sin(time * 2.2) * 0.05;
      out.armLeftRaise = restArmRaise - 0.08;
      out.gazeX = scan * 0.03;
      out.gazeY = -0.025;
    },
  },
  measure: {
    keyTime: 1.2,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out, 0.3);
      const extension = measureExtension(time);
      out.armRightForward = 1.05;
      out.armRightRaise = 0.05;
      out.armLeftForward = 1.2 - extension * 0.75;
      out.armLeftRaise = 0.05 + extension * 0.12;
      out.bodyYaw = -0.1 + extension * 0.18;
      out.bodyTiltX = 0.06;
      out.bodyTiltZ = extension * 0.04;
      out.gazeX = -0.02 - extension * 0.02;
      out.gazeY = -0.02;
    },
  },
  point: {
    keyTime: 0.7,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out);
      const jab = Math.max(0, Math.sin(time * 3.2)) ** 3;
      out.armRightRaise = 0.42 + jab * 0.08;
      out.armRightForward = 0.62 - jab * 0.08;
      out.bodyYaw = 0.2;
      out.bodyTiltZ = -0.04;
      out.bodyTiltX = 0.03 + jab * 0.02;
      out.gazeX = 0.035;
      out.gazeY = 0.01;
    },
  },
  read: {
    keyTime: 0.9,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out, 0.22);
      out.armLeftForward = 1.2;
      out.armRightForward = 1.2;
      out.armLeftRaise = 0.02;
      out.armRightRaise = 0.02;
      out.bodyTiltX = 0.09 + Math.sin(time * 0.9) * 0.015;
      out.gazeX = ((time * 0.55) % 1) * 0.06 - 0.03;
      out.gazeY = -0.03;
    },
  },
  type: {
    keyTime: 0.15,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out, 0.28);
      out.armLeftForward = 1.12;
      out.armRightForward = 1.12;
      out.armLeftRaise = -0.08 + Math.max(0, Math.sin(time * 19)) * 0.1;
      out.armRightRaise = -0.08 + Math.max(0, Math.sin(time * 19 + 2.1)) * 0.1;
      out.bodyTiltX = 0.07;
      out.bodySquash += Math.sin(time * 9.5) * 0.004;
      out.gazeY = -0.03;
      out.gazeX = Math.sin(time * 1.3) * 0.015;
    },
  },
  walk: {
    keyTime: 0.2,
    pose: (time, out) => {
      resetPose(out);
      stride(time, out, 9, 0.5);
      const swing = Math.sin(time * 9);
      out.armLeftForward = swing * 0.35;
      out.armRightForward = -swing * 0.35;
      out.bodyTiltX = 0.05;
    },
  },
  wave: {
    keyTime: 0.3,
    pose: (time, out) => {
      resetPose(out);
      breathe(time, out);
      out.armRightRaise = 1.05 + Math.sin(time * 9) * 0.3;
      out.armRightForward = 0.4;
      out.bodyTiltZ = 0.05 + Math.sin(time * 9) * 0.01;
      out.bodyYaw = 0.05;
      out.gazeY = 0.015;
    },
  },
} as const satisfies Record<AgentAction, ActionClip>;

export interface ReactionLook {
  x: number;
  y: number;
}

interface ReactionClip {
  duration: number;
  keyTime: number;
  pose: (time: number, out: Pose, look: ReactionLook) => void;
}

const window01 = (time: number, from: number, to: number) =>
  Math.min(1, Math.max(0, (time - from) / (to - from)));

const easeInOut = (value: number) =>
  value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2;

const wrapAngle = (angle: number) =>
  ((((angle + Math.PI) % tau) + tau) % tau) - Math.PI;

const blinkAt = (time: number, at: number) => {
  const local = (time - at) / 0.12;
  return local > 0 && local < 1 ? 1 - Math.sin(local * Math.PI) * 0.92 : 1;
};

export const reactionClips = {
  jump: {
    duration: 1.05,
    keyTime: 0.45,
    pose: (time, out) => {
      resetPose(out);
      const crouch = Math.sin(window01(time, 0, 0.22) * Math.PI);
      const air = window01(time, 0.2, 0.72);
      const land = Math.sin(window01(time, 0.72, 1) * Math.PI);
      const lift = Math.sin(air * Math.PI);
      out.rootY = lift * 0.6;
      out.bodySquash = 1 - crouch * 0.12 - land * 0.1 + lift * 0.05;
      out.armLeftRaise = restArmRaise + (lift + crouch * 0.2) * 1.25;
      out.armRightRaise = restArmRaise + (lift + crouch * 0.2) * 1.25;
      out.armLeftForward = lift * 0.3;
      out.armRightForward = lift * 0.3;
      out.leg0 = lift * 0.35;
      out.leg1 = -lift * 0.35;
      out.leg2 = lift * 0.35;
      out.leg3 = -lift * 0.35;
      out.gazeY = 0.02 * lift;
    },
  },
  look: {
    duration: 1.7,
    keyTime: 0.4,
    pose: (time, out, look) => {
      resetPose(out);
      breathe(time, out);
      const turn = easeInOut(window01(time, 0, 0.3));
      out.bodyYaw = look.x * 0.55 * turn;
      out.bodyTiltX = -look.y * 0.12 * turn;
      out.bodyTiltZ = -look.x * 0.04 * turn;
      out.gazeX = look.x * 0.045 * turn;
      out.gazeY = look.y * 0.035 * turn;
      out.eyeOpen = blinkAt(time, 0.55) * blinkAt(time, 0.8);
    },
  },
  peek: {
    duration: 1.7,
    keyTime: 0.7,
    pose: (time, out, look) => {
      resetPose(out);
      breathe(time, out);
      const side = look.x < 0 ? -1 : 1;
      const lean =
        easeInOut(window01(time, 0, 0.35)) *
        (1 - easeInOut(window01(time, 1.25, 1.7)));
      out.bodyTiltZ = -side * 0.42 * lean;
      out.rootY = lean * 0.04;
      out.gazeX = side * 0.05 * lean;
      out.gazeY = 0.01 * lean;
      if (side > 0) {
        out.armRightRaise = restArmRaise + lean * 0.5;
      } else {
        out.armLeftRaise = restArmRaise + lean * 0.5;
      }
      out.eyeOpen = blinkAt(time, 0.9);
    },
  },
  salute: {
    duration: 1.5,
    keyTime: 0.6,
    pose: (time, out) => {
      resetPose(out);
      const raise =
        easeInOut(window01(time, 0, 0.25)) *
        (1 - easeInOut(window01(time, 1.15, 1.4)));
      out.armRightRaise = restArmRaise + raise * 1.45;
      out.armRightForward = raise * 1.05;
      out.bodyTiltX = -0.06 * raise;
      out.bodySquash = 1 + raise * 0.035;
      out.gazeY = 0.015 * raise;
    },
  },
  shuffle: {
    duration: 1.9,
    keyTime: 0.2,
    pose: (time, out) => {
      resetPose(out);
      const beat = time * tau * 2.2;
      const step = Math.sin(beat);
      out.leg0 = step * 0.4;
      out.leg1 = step * 0.4;
      out.leg2 = -step * 0.4;
      out.leg3 = -step * 0.4;
      out.rootY = Math.abs(step) * 0.07;
      out.bodyTiltZ = step * 0.12;
      out.bodyYaw = Math.sin(beat / 2) * 0.32;
      out.armLeftRaise = restArmRaise + 0.5 + step * 0.45;
      out.armRightRaise = restArmRaise + 0.5 - step * 0.45;
      out.armLeftForward = 0.3;
      out.armRightForward = 0.3;
      out.bodySquash = 1 - Math.abs(Math.cos(beat)) * 0.04;
    },
  },
  spin: {
    duration: 1.15,
    keyTime: 0.3,
    pose: (time, out) => {
      resetPose(out);
      const turn = window01(time, 0.05, 1.05);
      const lift = Math.sin(turn * Math.PI);
      out.bodyYaw = wrapAngle(easeInOut(turn) * tau);
      out.rootY = lift * 0.18;
      out.armLeftRaise = restArmRaise + lift * 0.85;
      out.armRightRaise = restArmRaise + lift * 0.85;
      out.bodySquash = 1 + lift * 0.03;
    },
  },
  surprised: {
    duration: 1,
    keyTime: 0.3,
    pose: (time, out) => {
      resetPose(out);
      const hop = Math.sin(window01(time, 0, 0.36) * Math.PI);
      const startle = Math.min(1, time / 0.08) * (1 - window01(time, 0.7, 1));
      out.rootY = hop * 0.34;
      out.armLeftRaise = restArmRaise + startle * 1.2;
      out.armRightRaise = restArmRaise + startle * 1.2;
      out.armLeftForward = startle * 0.2;
      out.armRightForward = startle * 0.2;
      out.bodyTiltX = -0.14 * startle;
      out.bodySquash = 1 + hop * 0.06 - startle * 0.02;
      out.eyeOpen = 1 + startle * 0.4;
      out.gazeY = 0.02 * startle;
    },
  },
  wave: {
    duration: 1.6,
    keyTime: 0.3,
    pose: (time, out) => {
      actionClips.wave.pose(time, out);
      out.gazeY = 0.02;
    },
  },
} as const satisfies Record<AgentReaction, ReactionClip>;

export interface HopPlan {
  reachX: number;
  reachZ: number;
  turn: number;
}

export const hopClip = { duration: 1.75, keyTime: 0.9 } as const;

const bump = (time: number, from: number, to: number) =>
  Math.sin(window01(time, from, to) * Math.PI);

export const applyHop = (time: number, plan: HopPlan, out: Pose) => {
  const travel =
    easeInOut(window01(time, 0.1, 0.5)) - easeInOut(window01(time, 1.15, 1.58));
  const lift = bump(time, 0.1, 0.5) * 0.42 + bump(time, 1.15, 1.58) * 0.3;
  const crouch =
    bump(time, 0, 0.12) +
    bump(time, 0.5, 0.64) * 0.8 +
    bump(time, 1.03, 1.17) * 0.6 +
    bump(time, 1.58, 1.75) * 0.8;
  const turn = bump(time, 0.05, 0.62) - bump(time, 1.08, 1.64) * 0.75;
  out.rootX += plan.reachX * travel;
  out.rootZ += plan.reachZ * travel;
  out.rootY += lift;
  out.bodyYaw += plan.turn * turn;
  out.bodySquash += lift * 0.07 - crouch * 0.11;
  out.armLeftRaise += lift * 1.5;
  out.armRightRaise += lift * 1.5;
  out.leg0 += lift * 0.45;
  out.leg1 -= lift * 0.45;
  out.leg2 += lift * 0.45;
  out.leg3 -= lift * 0.45;
  out.gazeY += window01(time, 0.5, 0.7) * (1 - window01(time, 1, 1.15)) * 0.02;
};

export const applyHopReduced = (time: number, plan: HopPlan, out: Pose) => {
  if (time >= 0 && time < hopClip.duration) {
    out.rootX += plan.reachX;
    out.rootZ += plan.reachZ;
  }
};

"use client";

import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import type { RefObject } from "react";
import type { Group } from "three";
import { MathUtils } from "three";

import type { HopPlan } from "./actions";
import {
  actionClips,
  applyHop,
  applyHopReduced,
  hopClip,
  reactionClips,
} from "./actions";
import { createHopPlanner, createReactionDeck } from "./reaction-deck";
import type { Pose } from "./rig";
import { blendPoses, createPose } from "./rig";
import type { AgentAction, AgentReaction } from "./types";

export type AgentMotion = "full" | "reduced";

export interface AgentPointer {
  hovered: boolean;
  presses: number;
  x: number;
  y: number;
}

export interface RigNodes {
  armLeft: Group | null;
  armRight: Group | null;
  body: Group | null;
  eyes: Group | null;
  legs: (Group | null)[];
  root: Group | null;
  shadow: Group | null;
}

interface RigOptions {
  action: AgentAction;
  actionRef?: RefObject<AgentAction>;
  pointer: RefObject<AgentPointer>;
  motion: AgentMotion;
  seed: number;
}

interface Playback {
  blendFrom: AgentAction;
  blendStart: number;
  current: AgentAction;
  dealReaction: (() => AgentReaction) | null;
  hop: HopPlan | null;
  hopStart: number;
  planHop: (() => HopPlan) | null;
  presses: number;
  reaction: AgentReaction | null;
  reactionStart: number;
  wasHovered: boolean;
}

const blendSeconds = 0.38;
const blinkSeconds = 0.13;
const reactionInSeconds = 0.16;
const reactionOutSeconds = 0.28;
const reactionRetrigger = 0.55;

const smoothstep = (value: number) => {
  const clamped = MathUtils.clamp(value, 0, 1);
  return clamped * clamped * (3 - 2 * clamped);
};

const applyPose = (nodes: RigNodes, pose: Pose, blink: number) => {
  const { armLeft, armRight, body, eyes, legs, root, shadow } = nodes;
  if (shadow) {
    shadow.scale.setScalar(MathUtils.clamp(1 - pose.rootY * 1.6, 0.45, 1));
    shadow.position.set(pose.rootX, 0, pose.rootZ);
  }
  if (root) {
    root.position.set(pose.rootX, pose.rootY, pose.rootZ);
    root.rotation.y = pose.bodyYaw;
  }
  if (body) {
    const spread = 1 + (1 - pose.bodySquash) * 0.5;
    body.scale.set(spread, pose.bodySquash, spread);
    body.rotation.set(pose.bodyTiltX, 0, pose.bodyTiltZ);
  }
  if (armRight) {
    armRight.rotation.set(0, -pose.armRightForward, pose.armRightRaise);
  }
  if (armLeft) {
    armLeft.rotation.set(0, pose.armLeftForward, -pose.armLeftRaise);
  }
  const legAngles = [pose.leg0, pose.leg1, pose.leg2, pose.leg3];
  for (const [index, leg] of legs.entries()) {
    if (leg) {
      leg.rotation.x = legAngles[index] ?? 0;
    }
  }
  if (eyes) {
    eyes.position.x = pose.gazeX;
    eyes.position.y = pose.gazeY;
    eyes.scale.set(Math.max(1, pose.eyeOpen), blink * pose.eyeOpen, 1);
  }
};

const blinkAmount = (time: number, seed: number) => {
  const period = 3.4 + seed * 2.2;
  const phase = (time + seed * 11) % period;
  const doubleBlink =
    seed > 0.7 && phase > blinkSeconds * 1.6 && phase < blinkSeconds * 2.6;
  const local = doubleBlink ? phase - blinkSeconds * 1.6 : phase;
  if (local > blinkSeconds) {
    return 1;
  }
  return 1 - Math.sin((local / blinkSeconds) * Math.PI) * 0.9;
};

const trackHop = (track: Playback, presses: number, time: number) => {
  if (presses !== track.presses) {
    track.presses = presses;
    const plan = track.planHop ?? createHopPlanner();
    track.planHop = plan;
    track.hop = plan();
    track.hopStart = time;
  }
  const hopTime = time - track.hopStart;
  if (track.hop && hopTime >= hopClip.duration) {
    track.hop = null;
  }
  return hopTime;
};

export const useAgentRig = ({
  action: actionProp,
  actionRef,
  pointer,
  motion,
  seed,
}: RigOptions) => {
  const liveAction = useRef<AgentAction>(actionProp);
  const nodes = useRef<RigNodes>({
    armLeft: null,
    armRight: null,
    body: null,
    eyes: null,
    legs: [null, null, null, null],
    root: null,
    shadow: null,
  });
  const playback = useRef<Playback>({
    blendFrom: actionProp,
    blendStart: Number.NEGATIVE_INFINITY,
    current: actionProp,
    dealReaction: null,
    hop: null,
    hopStart: Number.NEGATIVE_INFINITY,
    planHop: null,
    presses: 0,
    reaction: null,
    reactionStart: Number.NEGATIVE_INFINITY,
    wasHovered: false,
  });
  const poses = useRef({
    from: createPose(),
    out: createPose(),
    reaction: createPose(),
    to: createPose(),
  });

  useFrame((state) => {
    const time = state.clock.elapsedTime;
    const track = playback.current;
    const { from, out, reaction, to } = poses.current;
    const action = actionRef?.current ?? actionProp;
    const look = pointer.current;
    liveAction.current = action;

    if (look.hovered && !track.wasHovered) {
      const playing = track.reaction
        ? (time - track.reactionStart) / reactionClips[track.reaction].duration
        : 1;
      if (playing >= reactionRetrigger) {
        const deal = track.dealReaction ?? createReactionDeck();
        track.dealReaction = deal;
        track.reaction = deal();
        track.reactionStart = time;
      }
    }
    track.wasHovered = look.hovered;
    const hopTime = trackHop(track, look.presses, time);
    const reactionTime = time - track.reactionStart;
    if (
      track.reaction &&
      reactionTime >= reactionClips[track.reaction].duration
    ) {
      track.reaction = null;
    }

    if (motion === "reduced") {
      if (track.reaction) {
        const clip = reactionClips[track.reaction];
        clip.pose(clip.keyTime, out, look);
        state.invalidate();
      } else {
        const clip = actionClips[action];
        clip.pose(clip.keyTime, out);
      }
      if (track.hop) {
        applyHopReduced(hopTime, track.hop, out);
        state.invalidate();
      }
      applyPose(nodes.current, out, 1);
      return;
    }

    if (action !== track.current) {
      track.blendFrom = track.current;
      track.current = action;
      track.blendStart = time;
    }

    actionClips[track.current].pose(time, to);
    const blend = smoothstep((time - track.blendStart) / blendSeconds);
    if (blend < 1) {
      actionClips[track.blendFrom].pose(time, from);
      blendPoses(from, to, blend, out);
    } else {
      blendPoses(to, to, 0, out);
    }

    if (track.reaction) {
      const clip = reactionClips[track.reaction];
      clip.pose(reactionTime, reaction, look);
      const weight =
        smoothstep(reactionTime / reactionInSeconds) *
        smoothstep((clip.duration - reactionTime) / reactionOutSeconds);
      blendPoses(out, reaction, weight, out);
    }

    if (track.hop) {
      applyHop(hopTime, track.hop, out);
    }

    applyPose(nodes.current, out, blinkAmount(time, seed));
  });

  const attach =
    (part: Exclude<keyof RigNodes, "legs">) => (node: Group | null) => {
      nodes.current[part] = node;
    };
  const attachLeg = (index: number) => (node: Group | null) => {
    nodes.current.legs[index] = node;
  };

  return { attach, attachLeg, liveAction };
};

import type { HopPlan } from "./actions";
import type { AgentReaction } from "./types";
import { agentReactions } from "./types";

const swapAt = (deck: AgentReaction[], from: number, to: number) => {
  const held = deck[from];
  const other = deck[to];
  if (held === undefined || other === undefined) {
    return;
  }
  deck[from] = other;
  deck[to] = held;
};

const shuffled = (random: () => number) => {
  const deck = [...agentReactions];
  for (let index = deck.length - 1; index > 0; index -= 1) {
    swapAt(deck, index, Math.floor(random() * (index + 1)));
  }
  return deck;
};

export const createReactionDeck = (random: () => number = Math.random) => {
  let deck: AgentReaction[] = [];
  let last: AgentReaction | null = null;
  return (): AgentReaction => {
    if (deck.length === 0) {
      deck = shuffled(random);
      if (deck.at(-1) === last) {
        swapAt(deck, 0, deck.length - 1);
      }
    }
    const next = deck.pop() ?? agentReactions[0];
    last = next;
    return next;
  };
};

export const createHopPlanner = (random: () => number = Math.random) => {
  let side = random() < 0.5 ? -1 : 1;
  return (): HopPlan => {
    side = -side;
    const reach = 0.32 + random() * 0.18;
    return {
      reachX: side * reach,
      reachZ: (random() - 0.5) * 0.24,
      turn: side * 0.85,
    };
  };
};

"use client";

import { useFrame } from "@react-three/fiber";
import { createContext, use, useRef } from "react";
import type { RefObject } from "react";
import type { Group, Object3D } from "three";
import { MathUtils } from "three";

import type { AgentAction } from "./types";
import type { AgentMotion } from "./use-agent-rig";

type Triple = readonly [number, number, number];

export interface HeldPose {
  position: Triple;
  rotation: Triple;
  facing?: number;
}

export const armPivotNames = { left: "arm-left", right: "arm-right" } as const;

const findArmPivot = (node: Object3D) => {
  let current = node.parent;
  while (current) {
    if (
      current.name === armPivotNames.left ||
      current.name === armPivotNames.right
    ) {
      return current;
    }
    current = current.parent;
  }
  return null;
};

const facingYaw = (pivot: Object3D | null, facing: number) => {
  if (!pivot) {
    return facing;
  }
  return pivot.name === armPivotNames.left
    ? pivot.rotation.y - facing
    : facing - pivot.rotation.y;
};

export interface AgentLiveState {
  dressing: RefObject<boolean>;
  liveAction: RefObject<AgentAction>;
  motion: AgentMotion;
}

export const AgentLiveContext = createContext<AgentLiveState | null>(null);

export const useAgentLive = () => {
  const live = use(AgentLiveContext);
  if (!live) {
    throw new Error("useAgentLive must be used inside an Agent");
  }
  return live;
};

const settleRate = 9;

export const useHeldPose = (
  rest: HeldPose,
  poses: Partial<Record<AgentAction, HeldPose>>
) => {
  const ref = useRef<Group>(null);
  const pivot = useRef<Object3D | null>(null);
  const { liveAction, motion } = useAgentLive();

  useFrame((_, delta) => {
    const group = ref.current;
    if (!group) {
      return;
    }
    const target = poses[liveAction.current] ?? rest;
    if (!pivot.current) {
      pivot.current = findArmPivot(group);
    }
    const yaw =
      target.facing === undefined
        ? target.rotation[1]
        : facingYaw(pivot.current, target.facing);
    const step =
      motion === "reduced"
        ? 1
        : 1 - Math.exp(-settleRate * Math.min(delta, 0.1));
    const { position, rotation } = group;
    position.set(
      MathUtils.lerp(position.x, target.position[0], step),
      MathUtils.lerp(position.y, target.position[1], step),
      MathUtils.lerp(position.z, target.position[2], step)
    );
    rotation.set(
      MathUtils.lerp(rotation.x, target.rotation[0], step),
      MathUtils.lerp(rotation.y, yaw, step),
      MathUtils.lerp(rotation.z, target.rotation[2], step)
    );
  });

  return { position: rest.position, ref, rotation: rest.rotation };
};

"use client";

import type { ThreeElements } from "@react-three/fiber";
import type { BufferGeometry } from "three";

import type { AgentMaterialName } from "./materials";
import { agentMaterials } from "./materials";

export interface PartProps extends Omit<
  ThreeElements["mesh"],
  "geometry" | "material" | "children"
> {
  geometry: BufferGeometry;
  material: AgentMaterialName;
}

export const Part = ({
  geometry,
  material,
  castShadow = false,
  receiveShadow = true,
  ...meshProps
}: PartProps) => (
  <mesh
    {...meshProps}
    castShadow={castShadow}
    geometry={geometry}
    material={agentMaterials[material]}
    receiveShadow={receiveShadow}
  />
);

import type { BufferGeometry } from "three";
import {
  BoxGeometry,
  CircleGeometry,
  CylinderGeometry,
  SphereGeometry,
  TorusGeometry,
} from "three";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";

const geometryCache = new Map<string, BufferGeometry>();

const shared = (key: string, create: () => BufferGeometry) => {
  const cached = geometryCache.get(key);
  if (cached) {
    return cached;
  }
  const geometry = create();
  geometryCache.set(key, geometry);
  return geometry;
};

export const roundedBox = (
  width: number,
  height: number,
  depth: number,
  radius: number,
  segments = 3
) =>
  shared(
    `rounded-box:${width}:${height}:${depth}:${radius}:${segments}`,
    () => new RoundedBoxGeometry(width, height, depth, segments, radius)
  );

export const cylinder = (radialSegments = 24) =>
  shared(
    `cylinder:${radialSegments}`,
    () => new CylinderGeometry(1, 1, 1, radialSegments)
  );

export const sphere = (widthSegments = 24) =>
  shared(
    `sphere:${widthSegments}`,
    () =>
      new SphereGeometry(1, widthSegments, Math.max(8, widthSegments * 0.75))
  );

export const dome = () =>
  shared(
    "dome",
    () => new SphereGeometry(1, 40, 20, 0, Math.PI * 2, 0, Math.PI / 2)
  );

export const torus = (tubeRatio: number, arc = Math.PI * 2) =>
  shared(
    `torus:${tubeRatio}:${arc}`,
    () => new TorusGeometry(1, tubeRatio, 12, 48, arc)
  );

export const disc = () => shared("disc", () => new CircleGeometry(1, 64));

export const box = () => shared("box", () => new BoxGeometry(1, 1, 1));

import {
  MeshBasicMaterial,
  MeshPhysicalMaterial,
  MeshStandardMaterial,
} from "three";

import {
  createGlyphTexture,
  createKnitBumpTexture,
  createPlaidTexture,
  createTweedTexture,
} from "./textures";

const knitBump = createKnitBumpTexture();
const glyphs = createGlyphTexture();

const matte = (color: string, roughness = 0.85) =>
  new MeshStandardMaterial({ color, roughness });

const plastic = (color: string, roughness = 0.4) =>
