      <group position={[-0.12, -0.1, 0.02]}>
        <group ref={blade} scale={[restingBlade, 1, 1]}>
          <Part
            geometry={boxGeometry}
            material="hardHatYellow"
            position={[-0.5, 0, 0]}
            scale={[1, 0.012, 0.06]}
